}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #495057;
}

.form-group .form-control,
.form-group .form-select {
    max-width: 480px;
}

/* Button row */
.button-row {
    display: flex;
    gap: 0.75rem;
