    flex-direction: column;
    gap: 0.25rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    cursor: pointer;
    max-width: 480px;
    margin-bottom: 0.25rem;
}

.toggle-row span {
    font-size: 0.95rem;
}

.toggle-switch {
    width: 2.5rem !important;
    height: 1.25rem;
    cursor: pointer;
    appearance: none;
    -webkit-appearance: none;
    background: #ccc;
    border-radius: 1rem;
    position: relative;
    transition: background 0.2s;
    border: none !important;
    flex-shrink: 0;
}

.toggle-switch:checked {
    background: #0d6efd;
}

.toggle-switch::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 1rem;
    height: 1rem;
    border-radius: 50%;
    background: white;
