}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #6c757d;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

.panel-body .form-group {
    margin-bottom: 1rem;
}

/* Two-factor */
.two-factor-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 480px;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.two-factor-info {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.two-factor-info h5 {
    margin: 0;
    font-size: 1rem;
}

.status-badge {
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-weight: 600;
}

.status-enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-disabled {
    background: #f8d7da;
    color: #842029;
}

/* Sessions table */
.table-responsive {
    margin-top: 0.75rem;
}

.table th {
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #6c757d;
    font-weight: 600;
}

/* Confirmation dialog */
.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1000;
}

.confirmation-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    background: white;
    border-radius: 12px;
    padding: 2rem;
    z-index: 1001;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
    min-width: 320px;
    text-align: center;
}

.confirmation-dialog h5 {
    margin-bottom: 0.75rem;
}

.confirmation-dialog .button-row {
    justify-content: center;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-weight: 400;
}

/* Preview area */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed #dee2e6;
    border-radius: 10px;
    max-width: 480px;
    transition: all 0.3s ease;
}

.preview-area h5 {
    margin-bottom: 0.5rem;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 1rem;
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.04);
}

.preview-card p {
    font-size: inherit;
    margin: 0.5rem 0;
}

/* Preview: theme variants */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-card {
    background: rgba(255, 255, 255, 0.08);
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

/* Preview: font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview: compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.4rem;
}

/* Toast */
.toast-message {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.85rem 1.5rem;
    border-radius: 8px;
    font-weight: 500;
    z-index: 2000;
    animation: slide-in 0.3s ease;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.toast-success {
    background: #198754;
    color: white;
}

.toast-error {
    background: #dc3545;
    color: white;
}

@keyframes slide-in {
    from {
        opacity: 0;
        transform: translateY(1rem);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

